import{_ as e,o as s,c as d,a2 as a}from"./chunks/framework.DbIb1qZn.js";const u=JSON.parse('{"title":"Benchmarks","description":"How Frensense is scored, the current OWASP Benchmark for Python record, and how to reproduce it.","frontmatter":{"title":"Benchmarks","description":"How Frensense is scored, the current OWASP Benchmark for Python record, and how to reproduce it."},"headers":[],"relativePath":"architecture/benchmarks.md","filePath":"architecture/benchmarks.md"}'),i={name:"architecture/benchmarks.md"};function n(r,t,o,h,l,c){return s(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h1><p>Frensense is scored against third-party ground truth, not only its own test corpus. The independent benchmark used today is the <strong>OWASP Benchmark for Python (v0.1)</strong>: 1,230 test cases written by the OWASP project, each labelled vulnerable or safe in an expected-results file. None of those cases appear in any Frensense knowledge bundle.</p><p>One benchmark is a narrow view. It covers a handful of vulnerability classes in one language, in small single-file programs. Read the numbers as a progress measure for the engine, not as a statement about how it performs on your code.</p><h2 id="published-record" tabindex="-1">Published record <a class="header-anchor" href="#published-record" aria-label="Permalink to &quot;Published record&quot;">​</a></h2><p>Scored on 2026-11-06 with Frensense 0.8.0 built from the <code>main</code> branch at commit <code>c2e6ade</code>. No <code>.frc</code> bundle (built-in knowledge only), single-file scans, conservative matching (see &quot;Scoring model&quot;).</p><table tabindex="0"><thead><tr><th>metric</th><th>value</th></tr></thead><tbody><tr><td><strong>Score (TPR - FPR)</strong></td><td><strong>31.0%</strong></td></tr><tr><td>TPR (vulnerable cases found)</td><td>38.1%</td></tr><tr><td>FPR (safe cases flagged)</td><td>7.1%</td></tr><tr><td>TP / FP / FN / TN</td><td>172 / 55 / 280 / 723</td></tr><tr><td>scan time</td><td>about 4 s for 1,230 cases (2 workers)</td></tr></tbody></table><p>Compared with the previous record (v0.7.0, 2026-10-02):</p><table tabindex="0"><thead><tr><th></th><th>v0.7.0</th><th>0.8.0 (<code>c2e6ade</code>)</th></tr></thead><tbody><tr><td>Score</td><td>26.2%</td><td>31.0%</td></tr><tr><td>TPR</td><td>28.5%</td><td>38.1%</td></tr><tr><td>FPR</td><td>2.3%</td><td>7.1%</td></tr><tr><td>TP / FP</td><td>129 / 18</td><td>172 / 55</td></tr></tbody></table><p>The engine finds more vulnerable cases, and it also raises more false alarms: the false-positive rate roughly tripled. Reducing it is an open engine priority, and many of the <a href="/challenges">challenges</a> target it.</p><p>We do not publish a ranking against other tools on this benchmark. The OWASP project&#39;s published scorecards are for the Java benchmark, a different language and test suite, so their numbers cannot be compared with these.</p><h2 id="per-category-results" tabindex="-1">Per-category results <a class="header-anchor" href="#per-category-results" aria-label="Permalink to &quot;Per-category results&quot;">​</a></h2><p>Lowest score first. A &quot;case&quot; is one test file. A finding counts for a vulnerable case only if it is attributed to that case&#39;s CWE.</p><table tabindex="0"><thead><tr><th>CWE</th><th>class</th><th>cases</th><th>TP</th><th>FP</th><th>FN</th><th>TN</th><th>TPR</th><th>FPR</th><th>score</th></tr></thead><tbody><tr><td>CWE-330</td><td>weak randomness</td><td>326</td><td>0</td><td>0</td><td>99</td><td>227</td><td>0.0%</td><td>0.0%</td><td>0.0%</td></tr><tr><td>CWE-79</td><td>cross-site scripting</td><td>89</td><td>0</td><td>0</td><td>31</td><td>58</td><td>0.0%</td><td>0.0%</td><td>0.0%</td></tr><tr><td>CWE-501</td><td>trust boundary</td><td>37</td><td>0</td><td>0</td><td>18</td><td>19</td><td>0.0%</td><td>0.0%</td><td>0.0%</td></tr><tr><td>CWE-90</td><td>LDAP injection</td><td>29</td><td>0</td><td>0</td><td>16</td><td>13</td><td>0.0%</td><td>0.0%</td><td>0.0%</td></tr><tr><td>CWE-611</td><td>XML external entities</td><td>28</td><td>0</td><td>0</td><td>8</td><td>20</td><td>0.0%</td><td>0.0%</td><td>0.0%</td></tr><tr><td>CWE-643</td><td>XPath injection</td><td>186</td><td>14</td><td>25</td><td>37</td><td>110</td><td>27.5%</td><td>18.5%</td><td>8.9%</td></tr><tr><td>CWE-94</td><td>code injection</td><td>53</td><td>11</td><td>14</td><td>9</td><td>19</td><td>55.0%</td><td>42.4%</td><td>12.6%</td></tr><tr><td>CWE-601</td><td>open redirect</td><td>34</td><td>8</td><td>7</td><td>5</td><td>14</td><td>61.5%</td><td>33.3%</td><td>28.2%</td></tr><tr><td>CWE-22</td><td>path traversal</td><td>168</td><td>26</td><td>6</td><td>39</td><td>97</td><td>40.0%</td><td>5.8%</td><td>34.2%</td></tr><tr><td>CWE-78</td><td>command injection</td><td>20</td><td>5</td><td>0</td><td>8</td><td>7</td><td>38.5%</td><td>0.0%</td><td>38.5%</td></tr><tr><td>CWE-89</td><td>SQL injection</td><td>16</td><td>2</td><td>0</td><td>3</td><td>11</td><td>40.0%</td><td>0.0%</td><td>40.0%</td></tr><tr><td>CWE-502</td><td>deserialization</td><td>54</td><td>11</td><td>3</td><td>7</td><td>33</td><td>61.1%</td><td>8.3%</td><td>52.8%</td></tr><tr><td>CWE-328</td><td>weak hash</td><td>151</td><td>71</td><td>0</td><td>0</td><td>80</td><td>100.0%</td><td>0.0%</td><td>100.0%</td></tr><tr><td>CWE-614</td><td>cookie flags</td><td>39</td><td>24</td><td>0</td><td>0</td><td>15</td><td>100.0%</td><td>0.0%</td><td>100.0%</td></tr></tbody></table><p>What this shows:</p><ul><li><strong>Five classes score zero.</strong> The built-in knowledge does not recognise the sources or sinks those cases use. Weak randomness alone is 99 vulnerable cases.</li><li><strong>Three classes have a high false-alarm rate</strong>: XPath injection, code injection and open redirect flag 18%, 42% and 33% of their safe cases. These are the classes where the safe variant looks most like the vulnerable one.</li><li><strong>Weak hashes and cookie flags are solved</strong> on this benchmark, because they need no data-flow reasoning.</li></ul><h2 id="reproduce-it-yourself" tabindex="-1">Reproduce it yourself <a class="header-anchor" href="#reproduce-it-yourself" aria-label="Permalink to &quot;Reproduce it yourself&quot;">​</a></h2><p>Requirements: Python 3.10+, git, and a built <code>frensense</code> binary (or Rust toolchain to auto-build).</p><h3 id="quick-reproduction-one-command-runner" tabindex="-1">Quick reproduction (one-command runner) <a class="header-anchor" href="#quick-reproduction-one-command-runner" aria-label="Permalink to &quot;Quick reproduction (one-command runner)&quot;">​</a></h3><p>From the root of the repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Automated run: auto-locates binary, caches OWASP suite, generates markdown &amp; JSON reports</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense-bench/run.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owasp</span></span></code></pre></div><p>This generates:</p><ul><li><code>benchmark_report.md</code>: formatted Markdown scorecard ready to share on GitHub Discussions or Gist.</li><li><code>benchmark_scorecard.json</code>: complete machine-readable scorecard with per-case verdicts (<code>TP</code>/<code>FP</code>/<code>FN</code>/<code>TN</code>).</li></ul><h3 id="sharing-via-github-gist" tabindex="-1">Sharing via GitHub Gist <a class="header-anchor" href="#sharing-via-github-gist" aria-label="Permalink to &quot;Sharing via GitHub Gist&quot;">​</a></h3><p>You can upload the scorecard directly to a GitHub Gist to share with the community:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># If GITHUB_TOKEN is exported in your environment:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense-bench/run.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> owasp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish-gist</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or manually upload the generated report:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Visit https://gist.github.com and paste the contents of benchmark_report.md</span></span></code></pre></div><h3 id="advanced-runner-flags" tabindex="-1">Advanced runner flags <a class="header-anchor" href="#advanced-runner-flags" aria-label="Permalink to &quot;Advanced runner flags&quot;">​</a></h3><p>You can also run the underlying Python runner directly with custom parameters:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frensense-bench/suites/owasp.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./target/release/frensense</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --md-out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark_report.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --json-out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark_scorecard.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/frensense-default.frc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # optional: measure bundle uplift</span></span></code></pre></div><h2 id="scoring-model" tabindex="-1">Scoring model <a class="header-anchor" href="#scoring-model" aria-label="Permalink to &quot;Scoring model&quot;">​</a></h2><p>The OWASP Benchmark accuracy metric, applied per case:</p><table tabindex="0"><thead><tr><th>expected</th><th>finding emitted</th><th>class</th></tr></thead><tbody><tr><td>vulnerable</td><td>yes, attributed to the case&#39;s CWE</td><td>TP</td></tr><tr><td>vulnerable</td><td>no</td><td>FN</td></tr><tr><td>safe</td><td>yes</td><td>FP</td></tr><tr><td>safe</td><td>no</td><td>TN</td></tr></tbody></table><p>The default matching mode is <code>conservative</code>: a finding counts as a true positive only when it is attributed to the CWE the case is about. A finding with no CWE attribution can never earn a true positive. <code>--match any</code> counts any finding on a vulnerable case and gives a more generous number, which is not comparable with the record above.</p><ul><li><code>TPR = TP / (TP + FN)</code> (recall on vulnerable cases)</li><li><code>FPR = FP / (FP + TN)</code> (false alarms on safe cases)</li><li><code>score = TPR - FPR</code></li></ul><p>A tool that flags everything scores 0. A tool that flags nothing scores 0. Precision and recall both matter, and the difference is what ranks real scanners.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Each case is scanned as a single file in its own process, so there is no cross-case state and no bundle influence: this measures the engine plus its built-in language specs.</li><li>Pass <code>--bundle &lt;file.frc&gt;</code> to the runner to measure what a bundle adds. A bundle can raise false alarms as well as detections, so compare both.</li><li>The per-CWE table is the tuning roadmap: the lowest-scoring classes with the most cases are where sink/source coverage work pays off most.</li></ul>`,36)])])}const k=e(i,[["render",n]]);export{u as __pageData,k as default};
